UPDATE sms_flash_promotion_product_relation
SET flash_promotion_sold_count = flash_promotion_sold_count + #{quantity}
WHERE id = #{relationId}
  AND flash_promotion_count - flash_promotion_sold_count >= #{quantity}

UPDATE sms_flash_promotion_product_relation
SET flash_promotion_sold_count = flash_promotion_sold_count - #{quantity}
WHERE id = #{relationId}
  AND flash_promotion_sold_count >= #{quantity}
